mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "status": {"type": "string", "description": "Only inquiries in this status, e.g. 受付. Empty or missing for all."}
  }
}

set-variable.value:
#[do {
            var raw = trim(payload.inquiryId default '')
            var digits = raw replace /^(?i)Q-?/ with ''
            ---
            if (digits matches /\d{1,4}/) 'Q-' ++ ((digits as Number) as String {format: '0000'}) else raw}]

mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "contextId": {"type": "string", "description": "The conversation (A2A contextId)"},
    "inquiryId": {"type": "string", "description": "Inquiry ID such as Q-0003"},
    "reply": {"type": "string", "description": "The reply to the customer, in Japanese"},
    "needsApproval": {"type": "string", "enum": ["true", "false"], "description": "Your own view: true when an employee should check the reply first"},
    "recommendation": {"type": "string", "enum": ["送信", "担当者対応"], "description": "For the approval inbox: send this draft, or let a person handle the customer"},
    "reasoning": {"type": "string", "description": "Why, 1 to 3 sentences (shown to the employee)"}
  },
  "required": ["contextId", "inquiryId", "reply", "needsApproval", "reasoning"]
}
